/** 명세서 기준 SSE 일회용 토큰과 이벤트 스트림 API입니다. */
package com.dandimate.durooduroo.notification.controller;
import com.dandimate.durooduroo.common.api.ApiResponse; import com.dandimate.durooduroo.common.auth.MemberTokenResolver; import com.dandimate.durooduroo.common.exception.BusinessException; import com.dandimate.durooduroo.member.repository.MemberRepository; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import java.time.Instant; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
@RestController public class EventController { private final MemberRepository members; private final Map<String,Token> tokens=new ConcurrentHashMap<>(); public EventController(MemberRepository m){members=m;}
 @PostMapping("/api/v1/rooms/{roomId}/event-token") public ApiResponse<?> token(@PathVariable String roomId,@RequestHeader(required=false) String authorization,@RequestParam(required=false) String memberToken){String access=MemberTokenResolver.resolve(authorization,memberToken);var me=members.findByRoomIdAndMemberToken(roomId,access).orElseThrow(()->new BusinessException("MEMBER_FORBIDDEN","참여자만 이벤트를 구독할 수 있습니다."));String value=UUID.randomUUID().toString();tokens.put(value,new Token(roomId,me.getId(),Instant.now().plusSeconds(60)));return ApiResponse.success(Map.of("streamToken",value,"expiresAt",Instant.now().plusSeconds(60)));}
 @GetMapping(value="/api/v1/rooms/{roomId}/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter events(@PathVariable String roomId,@RequestParam String streamToken){Token token=tokens.remove(streamToken);if(token==null||!token.roomId.equals(roomId)||token.expiresAt.isBefore(Instant.now()))throw new BusinessException("STREAM_TOKEN_INVALID","유효하지 않거나 만료된 스트림 토큰입니다.");SseEmitter emitter=new SseEmitter(60_000L);try{emitter.send(SseEmitter.event().name("connected").data(Map.of("roomId",roomId)));}catch(Exception e){emitter.completeWithError(e);}return emitter;}
 private record Token(String roomId,String memberId,Instant expiresAt){}
}
